-- Section F: metadata queries a Workbench-like GUI needs. Run with --force -B -N
SELECT 'F01 list tables', TABLE_NAME, TABLE_TYPE, ENGINE, TABLE_ROWS, DATA_LENGTH, TABLE_COLLATION, AUTO_INCREMENT, TABLE_COMMENT FROM information_schema.TABLES WHERE TABLE_SCHEMA='adv' ORDER BY TABLE_NAME;
SELECT 'F02 columns', TABLE_NAME, COLUMN_NAME, ORDINAL_POSITION, COLUMN_TYPE, DATA_TYPE, IS_NULLABLE, COLUMN_DEFAULT, COLUMN_KEY, EXTRA, CHARACTER_SET_NAME, COLLATION_NAME, GENERATION_EXPRESSION FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='school' AND TABLE_NAME='student' ORDER BY ORDINAL_POSITION;
SELECT 'F03 foreign keys (ER diagram)', k.CONSTRAINT_NAME, k.TABLE_NAME, k.COLUMN_NAME, k.REFERENCED_TABLE_SCHEMA, k.REFERENCED_TABLE_NAME, k.REFERENCED_COLUMN_NAME, r.UPDATE_RULE, r.DELETE_RULE
  FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME AND r.TABLE_NAME=k.TABLE_NAME
  WHERE k.TABLE_SCHEMA IN ('school','library_db','mydb') AND k.REFERENCED_TABLE_NAME IS NOT NULL ORDER BY k.TABLE_SCHEMA, k.TABLE_NAME;
SELECT 'F04 indexes', TABLE_NAME, INDEX_NAME, NON_UNIQUE, SEQ_IN_INDEX, COLUMN_NAME, INDEX_TYPE, CARDINALITY FROM information_schema.STATISTICS WHERE TABLE_SCHEMA='adv' AND TABLE_NAME IN ('art','emp') ORDER BY TABLE_NAME, INDEX_NAME, SEQ_IN_INDEX;
SELECT 'F05 check constraints', CONSTRAINT_SCHEMA, TABLE_NAME, CONSTRAINT_NAME, CHECK_CLAUSE FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA IN ('school','adv');
SELECT 'F06 routines', ROUTINE_NAME, ROUTINE_TYPE, DTD_IDENTIFIER, IS_DETERMINISTIC, DEFINER, LEFT(REPLACE(ROUTINE_DEFINITION,'\n',' '),40) FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA='adv' ORDER BY ROUTINE_NAME;
SELECT 'F07 routine params', SPECIFIC_NAME, ORDINAL_POSITION, PARAMETER_MODE, PARAMETER_NAME, DTD_IDENTIFIER FROM information_schema.PARAMETERS WHERE SPECIFIC_SCHEMA='adv' ORDER BY SPECIFIC_NAME, ORDINAL_POSITION;
SELECT 'F08 triggers', TRIGGER_NAME, EVENT_MANIPULATION, EVENT_OBJECT_TABLE, ACTION_TIMING, LEFT(REPLACE(ACTION_STATEMENT,'\n',' '),40) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='adv' ORDER BY TRIGGER_NAME;
SELECT 'F09 views', TABLE_NAME, IS_UPDATABLE, CHECK_OPTION, VIEW_DEFINITION FROM information_schema.VIEWS WHERE TABLE_SCHEMA='adv' ORDER BY TABLE_NAME;
SELECT 'F10 events', EVENT_NAME, STATUS, EVENT_TYPE, INTERVAL_VALUE, INTERVAL_FIELD FROM information_schema.EVENTS WHERE EVENT_SCHEMA='adv';
SELECT 'F11 schemata', SCHEMA_NAME, DEFAULT_CHARACTER_SET_NAME, DEFAULT_COLLATION_NAME FROM information_schema.SCHEMATA ORDER BY SCHEMA_NAME;
SELECT 'F12 SHOW CREATE TABLE';
SHOW CREATE TABLE school.student;
SELECT 'F12b SHOW CREATE VIEW / PROCEDURE / TRIGGER';
SHOW CREATE VIEW adv.v_it;
SHOW CREATE PROCEDURE adv.raise_dept;
SHOW CREATE TRIGGER adv.emp_bi;
SELECT 'F13 SHOW FULL PROCESSLIST';
SHOW FULL PROCESSLIST;
SELECT 'F13b information_schema.PROCESSLIST', ID, USER, HOST, DB, COMMAND, TIME, STATE, INFO FROM information_schema.PROCESSLIST;
SELECT 'F14 dashboard status', VARIABLE_NAME, VARIABLE_VALUE FROM information_schema.GLOBAL_STATUS WHERE VARIABLE_NAME IN ('QUESTIONS','THREADS_CONNECTED','UPTIME','BYTES_SENT','BYTES_RECEIVED','COM_SELECT','COM_INSERT','SLOW_QUERIES','CONNECTIONS','INNODB_BUFFER_POOL_PAGES_TOTAL') ORDER BY VARIABLE_NAME;
SELECT 'F14b SHOW GLOBAL STATUS LIKE';
SHOW GLOBAL STATUS WHERE Variable_name IN ('Questions','Threads_connected','Uptime','Bytes_sent');
SELECT 'F14c MySQL-8 style performance_schema.global_status (expect fail when PS off)';
SELECT * FROM performance_schema.global_status WHERE VARIABLE_NAME='Uptime';
SELECT 'F15 performance_schema enabled?', @@performance_schema;
SELECT 'F15b performance_schema tables exist', COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA='performance_schema';
SELECT 'F15c sys schema exists?', COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='sys';
SELECT 'F16 slow log toggle at runtime';
SET GLOBAL slow_query_log=1; SET GLOBAL long_query_time=0.2; SET GLOBAL log_output='TABLE';
SET SESSION long_query_time=0.2;
SELECT SLEEP(0.5) AS slept;
SELECT 'F16b slow log captured', COUNT(*), MAX(LEFT(sql_text,40)) FROM mysql.slow_log WHERE sql_text LIKE 'SELECT SLEEP(0.5)%';
SET GLOBAL slow_query_log=0; SET GLOBAL log_output='FILE';
SELECT 'F17 SET GLOBAL without restart';
SET GLOBAL max_connections=200; SET GLOBAL event_scheduler=ON; SET GLOBAL sql_mode='STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION'; SET GLOBAL innodb_buffer_pool_size=268435456; SET GLOBAL general_log=1; SET GLOBAL general_log=0;
SELECT 'F17b values', @@global.max_connections, @@global.event_scheduler, @@global.sql_mode, @@global.innodb_buffer_pool_size;
SELECT 'F17c read-only var (expect ERROR 1238)';
SET GLOBAL innodb_log_file_size=100663296;
SELECT 'F17d port read-only (expect ERROR 1238)';
SET GLOBAL port=3999;
SET GLOBAL max_connections=151; SET GLOBAL event_scheduler=OFF; SET GLOBAL sql_mode='STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION'; SET GLOBAL innodb_buffer_pool_size=134217728;
SELECT 'F18 SHOW VARIABLES/ENGINES/CHARSET/COLLATION counts';
SELECT 'F18 collations available', COUNT(*) FROM information_schema.COLLATIONS;
SELECT 'F18 engines', GROUP_CONCAT(ENGINE) FROM information_schema.ENGINES WHERE SUPPORT IN ('YES','DEFAULT');
SELECT 'F19 users via mysql.user', User, Host FROM mysql.user ORDER BY User;
SELECT 'F19b privileges info_schema', GRANTEE, PRIVILEGE_TYPE FROM information_schema.SCHEMA_PRIVILEGES WHERE TABLE_SCHEMA='adv';
SELECT 'F20 table sizes', TABLE_SCHEMA, ROUND(SUM(DATA_LENGTH+INDEX_LENGTH)/1024,1) kb FROM information_schema.TABLES GROUP BY TABLE_SCHEMA ORDER BY TABLE_SCHEMA;
SELECT 'F99 END';
